{"code": "import os
from PIL import Image, UnidentifiedImageError

valid_files = []
invalid_files = []

# Walk through the data_small directory
for root, dirs, files in os.walk("data_small"):
    for file in files:
        file_path = os.path.join(root, file)
        try:
            with Image.open(file_path) as img:
                size = os.path.getsize(file_path)
                if size > 1000:  # Reasonable image size threshold
                    valid_files.append((file_path, img.size, size))
        except UnidentifiedImageError:
            invalid_files.append(file_path)
        except Exception as e:
            invalid_files.append(file_path)

print(f"Valid images found: {len(valid_files)}")
print(f"Invalid/corrupted images: {len(invalid_files)}")

if valid_files:
    print("\nFirst few valid images:")
    for i, (path, size, file_size) in enumerate(valid_files[:5]):
        print(f"  {path} - Size: {size}, File size: {file_size} bytes")

    # Use the first valid file
    first_valid = valid_files[0][0]
    print(f"\nRecommended file to use: {first_valid}")
else:
    print("\nNo valid images found!")"}

